import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Activity, ArrowDownUp, ArrowRight, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, CloudUpload, Database, Download, FileCheck2, FileText, Landmark, LayoutDashboard, LockKeyhole, Menu, Plus, Search, ScrollText, Server, Settings2, ShieldCheck, TriangleAlert, UploadCloud, UserRound, X, BriefcaseBusiness, RefreshCw } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { helpDestinations, helpSections } from './helpContent';

type Page='overview'|'upload'|'history'|'datasets'|'jobs'|'settings'|'audit'|'help'|'detail';
type Org={_id:string;name:string;code:string};
type Readiness={adminConfigured:boolean;connectionTestConfigured:boolean;connectionTest:string;authorizationReady:boolean;liveExecutionEnabled:boolean;mainframeExecutionConfigured:boolean;reconciliationExecutionGateEnabled:boolean;reconciliationExecutionConfigured:boolean;reconciliationExecutionEnabled:boolean;reconciliationBlockers:string[];message:string};
type ConnectionResult={profile:string;state:'CLI_UNAVAILABLE'|'CONNECTION_FAILED'|'CONNECTION_VERIFIED'|'DATASET_ACCESS_FAILED'|'DATASET_ACCESS_VERIFIED';connectionStatus:'NOT_TESTED'|'VERIFIED'|'FAILED';datasetAccessStatus:'NOT_TESTED'|'VERIFIED'|'DENIED'|'FAILED';message:string;errorCategory?:string;dataset?:string;datasetAttributes?:{dsorg?:string;recfm?:string;lrecl?:number};executionEnabled:false};
type Run={runId:string;organizationName:string;status:string;stage?:string;profile:string;createdAt:string;completedAt?:string;jobId?:string;jobStatus?:string;returnCode?:number;eodDecision?:string;stepResults?:Array<{stage?:string;stepName?:string;status:string;returnCode?:number;conditionCode?:string;jobId?:string}>;datasetManifest?:Array<{name:string;purpose:string;state:string}>;cleanupStatus?:{state?:string;status?:string;warnings?:string[]};summary?:Record<string,number>;inputs?:{transaction?:{originalName:string;recordCount:number};settlement?:{originalName:string;recordCount:number}};diagnostics?:string[]};
type UploadInfo={uploadId:string;kind:string;originalName:string;size:number;recordCount:number;valid:boolean;errors:string[];preview:string[]};
type PlanPreview={planId:string;runId:string;organization:{id:string;name:string};profile:string;inputs:{transaction:{originalName:string;size:number;recordCount:number};settlement:{originalName:string;size:number;recordCount:number}};executable:false;datasets:Array<{name:string;purpose:string;format:string;space:string;state:string}>;steps:Array<{order:number;name:string;purpose:string;dependencies:string[];jobName?:string;jcl:string|null;jclUnavailableReason?:string;expectedDd:string[];checks:string[];state:string}>;cleanupManifest:{state:string;automaticCleanupEnabled:false;temporaryDatasetCandidates:string[];retainedDatasetCandidates:string[];policy:string};limitations:string[]};
type UploadSmoke={operationId:string;organizationId:string;organizationName:string;status:string;stage:string;runQualifier:string;inputs:{transaction:{originalName:string;size:number;recordCount:number};settlement:{originalName:string;size:number;recordCount:number}};datasets:Array<{name:string;kind:string;state:string;errorCategory?:string}>;stageResults:Record<string,unknown>;errorCategory?:string;errorMessage?:string;canStart?:boolean;gateMessage?:string};
type History={items:Run[];total:number;page:number;pageSize:number;totalPages:number};
type SmokeJob={operationId:string;template:'NOOP_SMOKE';jobName:string;state:string;jobId?:string;jobStatus?:string;returnCode?:number|null;conditionCode?:string;createdAt:string;submittedAt?:string;lastCheckedAt?:string;completedAt?:string;spoolText?:string;spoolTruncated?:boolean;spoolRetrievedAt?:string;errorCategory?:string;errorMessage?:string};
let csrfToken:string|undefined;
const api=async<T,>(url:string,init?:RequestInit):Promise<T>=>{const headers=new Headers(init?.headers);if(csrfToken&&init?.method&&init.method!=='GET')headers.set('X-CSRF-Token',csrfToken);const r=await fetch(url,{...init,headers,credentials:'include'});const body=await r.json().catch(()=>({}));if(!r.ok){if(body.code==='AUTHENTICATION_REQUIRED'||body.code==='OPERATOR_AUTH_NOT_CONFIGURED'){window.dispatchEvent(new CustomEvent('operator-auth-required',{detail:{code:body.code,message:body.message}}));}throw Object.assign(new Error(body.message??`Request failed (${r.status})`),{code:body.code,runId:body.runId});}return body as T;};
const navItems:{id:Page;label:string;icon:typeof LayoutDashboard;section:string}[]=[{id:'overview',label:'Overview',icon:LayoutDashboard,section:'WORKSPACE'},{id:'upload',label:'Upload & run',icon:CloudUpload,section:'WORKSPACE'},{id:'datasets',label:'Dataset explorer',icon:Database,section:'WORKSPACE'},{id:'jobs',label:'Jobs & spool',icon:BriefcaseBusiness,section:'WORKSPACE'},{id:'history',label:'Reports & history',icon:FileText,section:'WORKSPACE'},{id:'settings',label:'Mainframe readiness',icon:Settings2,section:'SYSTEM'},{id:'audit',label:'Audit logs',icon:ScrollText,section:'SYSTEM'},{id:'help',label:'Help & documentation',icon:BookOpen,section:'SYSTEM'}];
const statusLabel=(s:string)=>s.replace(/_/g,' ').toLowerCase().replace(/\b\w/g,m=>m.toUpperCase());
const fmt=(n?:number)=>n===undefined?'—':new Intl.NumberFormat('en-US').format(n);
const money=(n?:number)=>n===undefined?'Not available in current mainframe output':new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const dateTime=(v?:string)=>v?new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';

function App(){
 const [page,setPage]=useState<Page>('overview');const [orgs,setOrgs]=useState<Org[]>([]);const [orgId,setOrgId]=useState('');const [readiness,setReadiness]=useState<Readiness>();const [history,setHistory]=useState<History>({items:[],total:0,page:1,pageSize:8,totalPages:0});const [latest,setLatest]=useState<Run>();const [detail,setDetail]=useState<Run>();const [statusFilter,setStatusFilter]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);const [mobileOpen,setMobileOpen]=useState(false);const [profileOpen,setProfileOpen]=useState(false);const [signInOpen,setSignInOpen]=useState(false);const [authPrompt,setAuthPrompt]=useState('');const [loginError,setLoginError]=useState('');const [search,setSearch]=useState('');const [sort,setSort]=useState('createdAt');const [auth,setAuth]=useState<{authenticated:boolean;actorId?:string;configured:boolean}>({authenticated:false,configured:false});const [loginName,setLoginName]=useState('');const [loginPassword,setLoginPassword]=useState('');const [authBusy,setAuthBusy]=useState(false);
 const [authChecked,setAuthChecked]=useState(false);
 const clearProtectedData=useCallback(()=>{setHistory({items:[],total:0,page:1,pageSize:8,totalPages:0});setLatest(undefined);setDetail(undefined);},[]);
 const refresh=useCallback(async()=>{setLoading(true);setError('');try{const [o,r]=await Promise.all([api<Org[]>('/api/organizations'),api<Readiness>('/api/readiness')]);setOrgs(o);setOrgId((old)=>old||o[0]?._id||'');setReadiness(r);if(auth.authenticated){const h=await api<History>('/api/runs?page=1&pageSize=50');setHistory({...h,pageSize:8,items:h.items.slice(0,8)});setLatest(h.items[0]);}else clearProtectedData();}catch(e){setError(e instanceof Error?e.message:'Unable to load console data. Check the API and MongoDB.');}finally{setLoading(false);}},[auth.authenticated,clearProtectedData]);
 useEffect(()=>{void refresh();},[refresh]);
 useEffect(()=>{void api<{authenticated:boolean;actorId?:string;csrfToken?:string;configured:boolean}>('/api/auth/session').then(value=>{csrfToken=value.csrfToken;setAuth(value);}).catch(()=>setAuth({authenticated:false,configured:false})).finally(()=>setAuthChecked(true));},[]);
 useEffect(()=>{const blocked=(event:Event)=>{const detail=(event as CustomEvent<{message?:string;code?:string}>).detail;csrfToken=undefined;setAuth(current=>({...current,authenticated:false,actorId:undefined}));clearProtectedData();setAuthPrompt(detail?.code==='OPERATOR_AUTH_NOT_CONFIGURED'?'The server has not configured an application operator account. Set APP_OPERATOR_USERNAME and APP_OPERATOR_PASSWORD_SCRYPT on the API, then restart it.':detail?.message??'Your application session expired. Sign in again to continue.');};window.addEventListener('operator-auth-required',blocked);return()=>window.removeEventListener('operator-auth-required',blocked);},[clearProtectedData]);
 useEffect(()=>{const fn=()=>setPage('settings');window.addEventListener('open-readiness',fn);return()=>window.removeEventListener('open-readiness',fn);},[]);
 useEffect(()=>{const outside=(event:PointerEvent)=>{if(event.target instanceof Node&&!document.getElementById('operator-profile')?.contains(event.target))setProfileOpen(false);};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape'){setProfileOpen(false);setSignInOpen(false);}};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);};},[]);
 const openRun=async(runId:string)=>{try{const d=await api<Run>(`/api/runs/${encodeURIComponent(runId)}`);setDetail(d);setPage('detail');}catch(e){setError(e instanceof Error?e.message:'Could not load run.');}};
 const viewHistory=useCallback(async(p=1)=>{if(!auth.authenticated)return;try{const params=new URLSearchParams({page:String(p),pageSize:'8',sort,order:'desc'});if(search)params.set('search',search);if(statusFilter)params.set('status',statusFilter);const h=await api<History>(`/api/runs?${params}`);setHistory(h);}catch(e){setError(e instanceof Error?e.message:'Could not load history.');}},[auth.authenticated,search,sort,statusFilter]);
 useEffect(()=>{if(page==='history'&&auth.authenticated)void viewHistory(1);},[page,auth.authenticated,viewHistory]);
 const go=(to:Page)=>{setPage(to);setMobileOpen(false);};
 const signIn=async(e:React.FormEvent)=>{e.preventDefault();setAuthBusy(true);setLoginError('');try{const result=await api<{authenticated:boolean;actorId:string;csrfToken:string}>('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:loginName,password:loginPassword})});csrfToken=result.csrfToken;setAuth({authenticated:true,actorId:result.actorId,configured:true});setAuthPrompt('');setError('');setLoginPassword('');setSignInOpen(false);window.dispatchEvent(new Event('operator-authenticated'));}catch(e){const err=e as Error&{code?:string};if(err.code==='OPERATOR_AUTH_NOT_CONFIGURED'){setAuth(current=>({...current,configured:false}));setLoginError('Application authentication is not configured. The server administrator must set APP_OPERATOR_USERNAME and APP_OPERATOR_PASSWORD_SCRYPT.');}else setLoginError(err.message||'Sign-in failed.');}finally{setAuthBusy(false);}};
 const signOut=async()=>{try{await api('/api/auth/logout',{method:'POST'});csrfToken=undefined;setAuth(current=>({...current,authenticated:false,actorId:undefined}));clearProtectedData();setAuthPrompt('');setPage('overview');setProfileOpen(false);}catch(e){setError(e instanceof Error?e.message:'Sign out failed.');}};
 const showSignIn=()=>{setLoginError('');setSignInOpen(true);};
 const environmentLabel=import.meta.env.DEV?'LOCAL DEVELOPMENT':'APPLICATION ENVIRONMENT';
 const mainframeLabel=readiness?.liveExecutionEnabled?'READY':readiness?.mainframeExecutionConfigured?'CONNECTION NOT ESTABLISHED':'NOT CONFIGURED';
 return <div className="app-shell">
  <aside className={`sidebar ${mobileOpen?'sidebar-open':''}`}><div className="brand"><div className="brand-mark"><Landmark size={21}/></div><div><b>ledgerline</b><small>RECONCILIATION OPS</small></div><button className="icon-btn mobile-close" onClick={()=>setMobileOpen(false)} aria-label="Close menu"><X size={18}/></button></div>
   <nav aria-label="Main navigation"><div className="nav-label">WORKSPACE</div>{navItems.filter(n=>n.section==='WORKSPACE').map(n=><NavButton key={n.id} item={n} active={page===n.id} onClick={()=>go(n.id)}/>)}<div className="nav-label system-label">SYSTEM</div>{navItems.filter(n=>n.section==='SYSTEM').map(n=><NavButton key={n.id} item={n} active={page===n.id} onClick={()=>go(n.id)}/>)}</nav>
   <div className="sidebar-bottom"><div className="system-card"><div className="system-head"><span className="live-dot"/><span>Mainframe</span><span className="state-pill offline">{mainframeLabel}</span></div><p>{readiness?.message??'Checking backend readiness…'}</p><button onClick={()=>go('settings')}>Review readiness <ArrowRight size={13}/></button></div><div className="profile-wrap" id="operator-profile"><button type="button" className="profile" aria-haspopup="dialog" aria-expanded={profileOpen} aria-controls="operator-profile-panel" onClick={()=>setProfileOpen(open=>!open)}><div className="avatar">OK</div><div><b>Om Karkele</b><small>{auth.authenticated?`App session · ${auth.actorId}`:'ZID · Z73968 · display only'}</small></div><ChevronDown size={15} className={profileOpen?'chevron-up':''}/></button>{profileOpen&&<section className="profile-popover" id="operator-profile-panel" role="dialog" aria-label="Operator profile"><div className="profile-popover-title"><UserRound size={16}/><b>Operator profile</b></div><div className="profile-detail"><span>Name</span><strong>Om Karkele</strong></div><div className="profile-detail"><span>ZID</span><code>Z73968</code></div><div className="profile-detail"><span>Environment</span><strong>{environmentLabel}</strong></div><div className="profile-detail"><span>Application session</span><strong>{auth.authenticated?`Authenticated as ${auth.actorId}`:'Not authenticated'}</strong></div>{auth.authenticated?<button className="button-secondary" onClick={async()=>{try{await api('/api/auth/logout',{method:'POST'});csrfToken=undefined;setAuth({...auth,authenticated:false,actorId:undefined});setHistory({items:[],total:0,page:1,pageSize:8,totalPages:0});setLatest(undefined);setDetail(undefined);setPage('overview');}catch(e){setError(e instanceof Error?e.message:'Sign out failed.');}}}>Sign out</button>:auth.configured?<form className="auth-form" onSubmit={async e=>{e.preventDefault();setAuthBusy(true);try{const result=await api<{authenticated:boolean;actorId:string;csrfToken:string}>('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:loginName,password:loginPassword})});csrfToken=result.csrfToken;setAuth({authenticated:true,actorId:result.actorId,configured:true});setLoginPassword('');setProfileOpen(false);window.dispatchEvent(new Event('operator-authenticated'));}catch(e){setError(e instanceof Error?e.message:'Sign-in failed.');}finally{setAuthBusy(false);}}}><label>Configured operator username<input autoComplete="username" value={loginName} onChange={e=>setLoginName(e.target.value)} required maxLength={120}/></label><label>Password<input autoComplete="current-password" type="password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} required maxLength={1024}/></label><button className="button-primary" disabled={authBusy}>{authBusy?'Signing in…':'Sign in'}</button></form>:<p>Application authentication is not configured by the server administrator. Protected operations remain unavailable.</p>}<p>The displayed ZID is not proof of z/OS authentication. Mainframe profile credentials remain in the local Zowe secure profile.</p></section>}</div></div>
  </aside>
  {mobileOpen&&<button className="mobile-scrim" onClick={()=>setMobileOpen(false)} aria-label="Close menu"/>}
  <main className="main-area"><header className="topbar"><button className="icon-btn menu-trigger" onClick={()=>setMobileOpen(true)} aria-label="Open menu"><Menu size={19}/></button><div className="breadcrumb">Operations <span>/</span> <b>{page==='detail'?'Run details':navItems.find(n=>n.id===page)?.label}</b></div><div className="top-actions">{auth.authenticated?<><span className="session-indicator"><ShieldCheck size={14}/>App session · {auth.actorId}</span><button className="help-top-link sign-out-top" onClick={()=>void signOut()}>Sign out</button></>:<button className="button-primary sign-in-top" onClick={showSignIn}><LockKeyhole size={14}/>Sign in</button>}<button className="help-top-link" onClick={()=>go('help')}><CircleHelp size={15}/>Help</button><span className="env-badge"><span/>{environmentLabel}</span></div></header>
   <div className="content">
    {authPrompt&&!auth.authenticated&&<div className="auth-context-banner" role="status"><LockKeyhole size={17}/><span>{authPrompt}</span>{auth.configured?<button className="text-btn" onClick={showSignIn}>Sign in <ArrowRight size={14}/></button>:<button className="text-btn" onClick={()=>go('help')}>View setup guidance <ArrowRight size={14}/></button>}<button className="icon-btn" onClick={()=>setAuthPrompt('')} aria-label="Dismiss sign-in notice"><X size={16}/></button></div>}
    {error&&<div className="alert alert-error"><TriangleAlert size={17}/><span>{error}</span><button onClick={()=>setError('')} aria-label="Dismiss"><X size={16}/></button></div>}
    {loading&&<div className="loading-line"><span/> Connecting to operations API…</div>}
    {page==='overview'&&<Overview orgs={orgs} latest={latest} runs={history.items} readiness={readiness} onRun={openRun} onUpload={()=>go('upload')} onHistory={()=>go('history')} onSettings={()=>go('settings')}/>}
    {page==='upload'&&(auth.authenticated?<UploadPage orgs={orgs} orgId={orgId} onOrg={setOrgId} readiness={readiness} onRefresh={refresh} onError={setError}/>:<ProtectedFeature name="Upload & run" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    {page==='history'&&(auth.authenticated?<HistoryPage data={history} search={search} onSearch={setSearch} status={statusFilter} onStatus={setStatusFilter} sort={sort} onSort={setSort} onQuery={()=>void viewHistory(1)} onPage={viewHistory} onOpen={openRun}/>:<ProtectedFeature name="Reports & history" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    {page==='datasets'&&(auth.authenticated?<DatasetExplorerPage/>:<ProtectedFeature name="Dataset Explorer" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    {page==='jobs'&&(auth.authenticated?<JobsSpoolPage onOpenRun={openRun}/>:<ProtectedFeature name="Jobs & spool" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    {page==='settings'&&<SettingsPage readiness={readiness} orgs={orgs} onOrgs={setOrgs} onOrg={setOrgId} onError={setError}/>}
    {page==='audit'&&(auth.authenticated?<AuditLogsPage/>:<ProtectedFeature name="Audit logs" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    {page==='help'&&<HelpCenterPage onNavigate={go}/>}
    {page==='detail'&&detail&&(auth.authenticated?<DetailPage run={detail} onBack={()=>go('history')}/>:<ProtectedFeature name="Run details and reports" authChecked={authChecked} configured={auth.configured} onSignIn={showSignIn}/>)}
    <footer className="footer"><span>LEDGERLINE RECONCILIATION CONSOLE</span><span>z/OS execution is controlled by your backend administrator.</span></footer>
   </div>
  </main>
  {signInOpen&&<div className="auth-dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setSignInOpen(false);}}><section className="auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-dialog-title"><button className="modal-close" onClick={()=>setSignInOpen(false)} aria-label="Close sign-in dialog"><X size={18}/></button><span className="eyebrow">APPLICATION ACCESS</span><h2 id="auth-dialog-title">Sign in to Ledgerline</h2>{!authChecked?<p role="status">Checking server authentication configuration…</p>:!auth.configured?<div className="auth-setup"><p>Application operator authentication is not configured on this server. A sign-in form is unavailable.</p><p>Ask the server administrator to configure <code>APP_OPERATOR_USERNAME</code> and a valid <code>APP_OPERATOR_PASSWORD_SCRYPT</code> hash, then restart the API. No default credentials are provided.</p></div>:<form className="auth-form auth-dialog-form" onSubmit={signIn}><label>Operator username<input autoComplete="username" value={loginName} onChange={e=>setLoginName(e.target.value)} required maxLength={120} autoFocus/></label><label>Password<input autoComplete="current-password" type="password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} required maxLength={1024}/></label>{loginError&&<p className="auth-form-error" role="alert">{loginError}</p>}<button className="button-primary" disabled={authBusy}>{authBusy?'Signing in…':'Sign in'}</button></form>}<p className="auth-distinction">Application operator sign-in is separate from the Zowe `zosmf` profile connection test. The displayed ZID does not authenticate either session.</p></section></div>}
 </div>
}
function NavButton({item,active,onClick}:{item:typeof navItems[number];active:boolean;onClick:()=>void}){const Icon=item.icon;return <button className={`nav-item ${active?'active':''}`} onClick={onClick} aria-current={active?'page':undefined}><Icon size={17}/><span>{item.label}</span>{active&&<i/>}</button>}
function ProtectedFeature({name,authChecked,configured,onSignIn}:{name:string;authChecked:boolean;configured:boolean;onSignIn:()=>void}){return <section className="protected-feature panel" aria-live="polite"><div className="protected-icon"><LockKeyhole size={20}/></div><div><span className="eyebrow">APPLICATION SESSION REQUIRED</span><h2>{name} is protected</h2>{!authChecked?<p>Checking the server-configured application authentication…</p>:configured?<><p>Sign in with the operator account configured by the server administrator. Mainframe connection status does not sign you in to this application.</p><button className="button-primary" onClick={onSignIn}><LockKeyhole size={15}/>Sign in to continue</button></>:<><p>Application authentication is not configured, so this protected feature cannot be opened.</p><p>Ask the API administrator to set <code>APP_OPERATOR_USERNAME</code> and a valid <code>APP_OPERATOR_PASSWORD_SCRYPT</code> hash, then restart the server. No default account is available.</p></>}</div></section>}
function PageHeading({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Overview({orgs,latest,runs,readiness,onRun,onUpload,onHistory,onSettings}:{orgs:Org[];latest?:Run;runs:Run[];readiness?:Readiness;onRun:(id:string)=>void;onUpload:()=>void;onHistory:()=>void;onSettings:()=>void}){
 const latestCompleted=runs.find(r=>r.status==='COMPLETED'||r.status==='BUSINESS_EXCEPTION');const s=latestCompleted?.summary??{};const hasExceptionCounts=s.mismatchedCount!==undefined&&s.transactionOnlyCount!==undefined&&s.settlementOnlyCount!==undefined;const exceptionTotal=hasExceptionCounts?s.mismatchedCount!+s.transactionOnlyCount!+s.settlementOnlyCount!:undefined;const maxAmount=Math.max(s.transactionAmount??0,s.settlementAmount??0,s.validatedAmount??0,1);const trend=runs.filter(r=>r.status==='COMPLETED'||r.status==='BUSINESS_EXCEPTION').slice(0,7).reverse().map(r=>({run:r.runId.slice(-6),matched:r.summary?.matchedCount??null,exceptions:r.summary?.mismatchedCount!==undefined&&r.summary.transactionOnlyCount!==undefined&&r.summary.settlementOnlyCount!==undefined?r.summary.mismatchedCount+r.summary.transactionOnlyCount+r.summary.settlementOnlyCount:null}));
 const hasFullFlowCounts=['matchedCount','mismatchedCount','transactionOnlyCount','settlementOnlyCount'].every(key=>s[key]!==undefined);const flow=[{name:'Transactions',value:latestCompleted?.inputs?.transaction?.recordCount??0,color:'#46c8c1'},{name:'Matched',value:s.matchedCount??0,color:'#68bcae'},{name:'Exceptions',value:(s.mismatchedCount??0)+(s.transactionOnlyCount??0)+(s.settlementOnlyCount??0),color:'#e0a86d'}];const totalIn=flow[0].value;
 return <><PageHeading eyebrow="OPERATIONS" title="Reconciliation overview" description="Saved run activity and current mainframe readiness." action={<button className="button-primary" onClick={onUpload}><Plus size={16}/> New reconciliation</button>}/>
  <div className="welcome-strip"><div className="welcome-icon"><Activity size={19}/></div><div><b>{orgs.length?`${orgs.length} organization${orgs.length===1?'':'s'} configured`:'Set up your organization'}</b><span>{orgs.length?'Select an organization when preparing your next reconciliation run.':'Add organization metadata in readiness settings to begin.'}</span></div><div className="welcome-right"><span className={`state-pill ${readiness?.liveExecutionEnabled?'online':'offline'}`}><i/>{readiness?.liveExecutionEnabled?'READY':'NOT CONFIGURED'}</span><small>MAINFRAME EXECUTION</small></div></div>
  <div className="section-title"><div><h2>Latest run snapshot</h2><span>{latestCompleted?`Based on ${latestCompleted.runId}`:'Latest completed mainframe data'}</span></div>{latest&&<button className="text-btn" onClick={()=>onRun(latest.runId)}>View latest run <ArrowRight size={14}/></button>}</div>
  {latestCompleted?<div className="metric-grid"><Metric label="Transaction records" value={fmt(latestCompleted.inputs?.transaction?.recordCount)} note="Saved upload metadata" icon={<FileText/>} tone="blue"/><Metric label="Settlement records" value={fmt(latestCompleted.inputs?.settlement?.recordCount)} note="Saved upload metadata" icon={<Database/>} tone="slate"/><Metric label="Matched records" value={fmt(s.matchedCount)} note="Verified mainframe report" icon={<Check/>} tone="mint"/><Metric label="Exception records" value={fmt(exceptionTotal)} note={<span>Mismatch {fmt(s.mismatchedCount)} · Transaction only {fmt(s.transactionOnlyCount)} · Settlement only {fmt(s.settlementOnlyCount)}</span>} icon={<TriangleAlert/>} tone="amber"/></div>:<section className="empty-run-state"><div className="empty-run-icon"><Activity size={19}/></div><div><span className="section-kicker">NO COMPLETED REPORTS</span><h2>{orgs.length?'Your run history is ready for its first verified result':'Set up an organization to begin'}</h2><p>{orgs.length?'This overview will show saved upload counts and mainframe results after a completed run. No reconciliation data is available yet.':'Add an organization first. Its name will be attached to uploads, run history and reports.'}</p><div className="empty-run-actions"><button className="button-primary" onClick={orgs.length?onUpload:onSettings}>{orgs.length?'Prepare an upload':'Set up organization'} <ArrowRight size={14}/></button><button className="button-secondary" onClick={onSettings}>Review mainframe readiness</button></div></div></section>}
  {latest&&<div className="last-run-strip"><span className="last-run-label">LATEST REQUEST</span><Status status={latest.status}/><span><small>JES JOB</small><code>{latest.jobId??'Not submitted'}</code></span><span><small>RETURN CODE</small><code>{latest.returnCode??'—'}</code></span><span><small>EOD PUBLICATION</small><b>{latest.eodDecision??'Not available'}</b></span><span className="last-run-date">{dateTime(latest.createdAt)}</span></div>}
  <div className="data-grid"><section className="panel flow-panel"><div className="panel-head"><div><h3>Reconciliation flow</h3><p>{latestCompleted?`Verified output · ${latestCompleted.runId}`:'Flow appears after the first completed mainframe run'}</p></div><span className="mini-tag">RECORDS</span></div>{latestCompleted&&hasFullFlowCounts&&totalIn>0&&flow[1].value+flow[2].value>0?<><div className="flow-chart"><div className="flow-node source"><strong>{fmt(flow[0].value)}</strong><span>Transactions in</span></div><div className="flow-links"><div className="flow-link match-link"/><div className="flow-link exception-link"/></div><div className="flow-destinations"><div className="flow-node matched"><strong>{fmt(flow[1].value)}</strong><span>Matched</span></div><div className="flow-node exception"><strong>{fmt(flow[2].value)}</strong><span>Exception categories</span></div></div></div><div className="flow-legend"><span><i className="mint-key"/>Matched {fmt(s.matchedCount)}</span><span><i className="amber-key"/>Mismatched {fmt(s.mismatchedCount)}</span><span><i className="gray-key"/>Transaction only {fmt(s.transactionOnlyCount)} · Settlement only {fmt(s.settlementOnlyCount)}</span></div></>:<EmptyViz icon={<ArrowDownUp/>} title="Verified flow counts unavailable" text="This flow appears when a completed mainframe report supplies every reconciliation category."/>}</section>
   <section className="panel amount-panel"><div className="panel-head"><div><h3>Amount reconciliation</h3><p>{latestCompleted?`Report totals · ${latestCompleted.runId}`:'Awaiting reported financial totals'}</p></div><span className="mini-tag">UNIT NOT SPECIFIED</span></div>{s.transactionAmount!==undefined||s.settlementAmount!==undefined||s.validatedAmount!==undefined?<><div className="amount-bars"><AmountBar label="Transactions" value={s.transactionAmount} max={maxAmount}/><AmountBar label="Settlements" value={s.settlementAmount} max={maxAmount}/><AmountBar label="Validated amount" value={s.validatedAmount} max={maxAmount}/></div><div className="discrepancy-callout"><span>Reported discrepancy</span><b>{money(s.discrepancyAmount)}</b></div></>:<EmptyViz icon={<ArrowDownUp/>} title="Financial totals unavailable" text="Not available in current mainframe output. Amounts will appear when a verified report provides them."/>}<div className="definition">Discrepancy comes from the mainframe report. Currency is unspecified; the console does not derive validated amounts.</div></section></div>
  <div className="lower-grid"><section className="panel trend-panel"><div className="panel-head"><div><h3>Run trend</h3><p>Matched records and exceptions across completed runs</p></div><span className="mini-tag">LAST 7 RUNS</span></div>{trend.length>=2?<div className="trend-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend} margin={{top:12,right:12,left:-22,bottom:0}}><defs><linearGradient id="matchedFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#45c7bf" stopOpacity={.22}/><stop offset="95%" stopColor="#45c7bf" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#26343c" vertical={false}/><XAxis dataKey="run" axisLine={false} tickLine={false} tick={{fill:'#819099',fontSize:10}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#819099',fontSize:10}}/><Tooltip contentStyle={{background:'#17232b',border:'1px solid #30414a',borderRadius:8,color:'#e8eff0'}}/><Area type="monotone" dataKey="matched" name="Matched" stroke="#50c7bf" fill="url(#matchedFill)" strokeWidth={2}/><Area type="monotone" dataKey="exceptions" name="Exceptions" stroke="#d5a367" fill="transparent" strokeWidth={2}/></AreaChart></ResponsiveContainer></div>:<EmptyViz icon={<Activity/>} title="Trend needs more run history" text="Two or more completed runs are required to show a trend."/>}</section>
  <section className="panel readiness-panel"><div className="panel-head"><div><h3>Mainframe readiness</h3><p>Backend controlled integration status</p></div><Server size={17} className="muted-icon"/></div><ReadinessRows readiness={readiness}/><button className="outline-full" onClick={()=>{window.dispatchEvent(new CustomEvent('open-readiness'));}}>Review configuration <ArrowRight size={14}/></button></section></div>
  <section className="panel recent-panel"><div className="panel-head"><div><h3>Recent runs</h3><p>Most recent requests across organizations</p></div><button className="text-btn" onClick={onHistory}>View history <ArrowRight size={14}/></button></div>{runs.length?<div className="table-wrap"><table><thead><tr><th>RUN ID</th><th>ORGANIZATION</th><th>SUBMITTED</th><th>TRANSACTIONS</th><th>STATUS</th><th/></tr></thead><tbody>{runs.slice(0,5).map(r=><tr key={r.runId} onClick={()=>onRun(r.runId)}><td><code>{r.runId}</code></td><td>{r.organizationName}</td><td>{dateTime(r.createdAt)}</td><td>{fmt(r.inputs?.transaction?.recordCount)}</td><td><Status status={r.status}/></td><td><ArrowRight size={15}/></td></tr>)}</tbody></table></div>:<div className="table-empty"><FileCheck2 size={19}/><span>No runs have been submitted.</span><button onClick={onUpload}>Prepare an upload</button></div>}</section>
 </>;
}
function Metric({label,value,note,icon,tone}:{label:string;value:string;note:React.ReactNode;icon:React.ReactNode;tone:string}){return <div className="metric"><div className="metric-top"><span>{label}</span><i className={`metric-icon ${tone}`}>{icon}</i></div><strong className={value.startsWith('Not available')?'metric-unavailable':''}>{value}</strong><small>{note}</small></div>}
function EmptyViz({icon,title,text}:{icon:React.ReactNode;title:string;text:string}){return <div className="viz-empty"><span>{icon}</span><b>{title}</b><p>{text}</p></div>}
function AmountBar({label,value,max}:{label:string;value?:number;max:number}){return <div className="amount-row"><div><span>{label}</span><b>{money(value)}</b></div><div className="amount-track"><i style={{width:value===undefined?'0%':`${Math.max(2,value/max*100)}%`}}/></div></div>}
function Status({status}:{status:string}){const cls=status.toLowerCase().replace(/_/g,'-');return <span className={`status ${cls}`}><i/>{statusLabel(status)}</span>}
function ReadinessRows({readiness,connectionOverride}:{readiness?:Readiness;connectionOverride?:ConnectionResult['state']}){const r=readiness;const connectionLabel=connectionOverride==='DATASET_ACCESS_VERIFIED'?'Verified':connectionOverride==='DATASET_ACCESS_FAILED'?'Connection verified; dataset unavailable':connectionOverride==='CONNECTION_VERIFIED'?'Connection verified':connectionOverride==='CONNECTION_FAILED'?'Connection failed':connectionOverride==='CLI_UNAVAILABLE'?'Zowe CLI unavailable':r?.connectionTest==='PASSED'?'Verified':'Not tested';const connectionOk=connectionOverride==='DATASET_ACCESS_VERIFIED'||connectionOverride==='CONNECTION_VERIFIED'||r?.connectionTest==='PASSED';return <div className="readiness-rows"><ReadinessRow label="Administrator config" value={r?.adminConfigured?'Present':'Not configured'} ok={Boolean(r?.adminConfigured)}/><ReadinessRow label="Connection test" value={connectionLabel} ok={connectionOk}/><ReadinessRow label="Operator authorization" value={r?.authorizationReady?'Ready':'Not configured'} ok={Boolean(r?.authorizationReady)}/><ReadinessRow label="Reconciliation gate" value={r?.reconciliationExecutionGateEnabled?'Enabled':'Disabled'} ok={Boolean(r?.reconciliationExecutionGateEnabled)}/><ReadinessRow label="Reconciliation executor" value={r?.reconciliationExecutionConfigured?'Configured':'Not configured'} ok={Boolean(r?.reconciliationExecutionConfigured)}/><ReadinessRow label="Live execution" value={r?.liveExecutionEnabled?'Enabled':'Disabled'} ok={Boolean(r?.liveExecutionEnabled)}/></div>}
function ReadinessRow({label,value,ok}:{label:string;value:string;ok:boolean}){return <div className="readiness-row"><span>{label}</span><b className={ok?'yes':'no'}><i/>{value}</b></div>}
function UploadPage({orgs,orgId,onOrg,readiness,onRefresh,onError}:{orgs:Org[];orgId:string;onOrg:(s:string)=>void;readiness?:Readiness;onRefresh:()=>void;onError:(s:string)=>void}){
 const [txn,setTxn]=useState<UploadInfo>();const [settle,setSettle]=useState<UploadInfo>();const [profile,setProfile]=useState('SMOKE');const [orgName,setOrgName]=useState('');const [orgCode,setOrgCode]=useState('');const [newOrg,setNewOrg]=useState(false);const [notice,setNotice]=useState('');const [plan,setPlan]=useState<PlanPreview>();const [planBusy,setPlanBusy]=useState(false);const [expandedJcl,setExpandedJcl]=useState<number>();const [smokePlan,setSmokePlan]=useState<UploadSmoke>();const [smokeBusy,setSmokeBusy]=useState(false);const [smokeConfirm,setSmokeConfirm]=useState(false);const [smokeAcknowledged,setSmokeAcknowledged]=useState(false);
 const submitFile=async(kind:'transaction'|'settlement',file?:File)=>{if(!file)return;if(!orgId){onError('Create or select an organization before uploading files.');return;}if(!file.name.toLowerCase().endsWith('.txt')){onError('Only .txt files are accepted.');return;}const body=new FormData();body.append('file',file);body.append('organizationId',orgId);try{const data=await api<UploadInfo>(`/api/uploads/${kind}`,{method:'POST',body});(kind==='transaction'?setTxn:setSettle)(data);setPlan(undefined);setSmokePlan(undefined);setSmokeAcknowledged(false);setNotice(data.valid?`${data.originalName} passed the basic file-contract checks.`:`${data.originalName} needs attention before a run can be requested.`);}catch(e){onError(e instanceof Error?e.message:'Upload failed.');}};
 const createOrg=async(e:React.FormEvent)=>{e.preventDefault();try{const org=await api<Org>('/api/organizations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:orgName,code:orgCode})});onOrg(org._id);setNotice(`${org.name} added.`);setOrgName('');setOrgCode('');setNewOrg(false);onRefresh();}catch(e){onError(e instanceof Error?e.message:'Could not create organization.');}};
 const previewPlan=async()=>{if(!txn||!settle)return;setPlanBusy(true);setPlan(undefined);try{const value=await api<PlanPreview>('/api/runs/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:orgId,transactionUploadId:txn.uploadId,settlementUploadId:settle.uploadId,profile})});setPlan(value);setExpandedJcl(undefined);}catch(e){onError(e instanceof Error?e.message:'Could not build the execution-plan preview.');}finally{setPlanBusy(false);}};
 const previewSmoke=async()=>{if(!txn||!settle)return;setSmokeBusy(true);setSmokePlan(undefined);setSmokeAcknowledged(false);try{const value=await api<UploadSmoke>('/api/mainframe/upload-verification/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:orgId,transactionUploadId:txn.uploadId,settlementUploadId:settle.uploadId})});setSmokePlan(value);}catch(e){onError(e instanceof Error?e.message:'Could not prepare the file-transfer verification.');}finally{setSmokeBusy(false);}};
 const startSmoke=async()=>{if(!smokePlan||!smokeAcknowledged)return;setSmokeBusy(true);try{const result=await api<UploadSmoke>(`/api/mainframe/upload-verification/${encodeURIComponent(smokePlan.operationId)}/start`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmDatasets:smokePlan.datasets.map(d=>d.name)})});setSmokePlan({...smokePlan,...result});setSmokeConfirm(false);setSmokeAcknowledged(false);}catch(e){onError(e instanceof Error?e.message:'File-transfer verification could not be started.');}finally{setSmokeBusy(false);}};
 const refreshSmoke=useCallback(async()=>{if(!smokePlan?.operationId)return;try{const value=await api<UploadSmoke>(`/api/mainframe/upload-verification/${encodeURIComponent(smokePlan.operationId)}`);setSmokePlan(old=>old?.operationId===value.operationId?{...old,...value}:old);}catch{/* preserve the last persisted status while the API reconnects */}},[smokePlan?.operationId]);
 useEffect(()=>{if(smokePlan?.status!=='RUNNING')return;const timer=window.setTimeout(()=>void refreshSmoke(),1800);return()=>window.clearTimeout(timer);},[smokePlan?.status,smokePlan?.stage,refreshSmoke]);
 const retrySmokeCleanup=async()=>{if(!smokePlan)return;setSmokeBusy(true);try{const value=await api<UploadSmoke>(`/api/mainframe/upload-verification/${encodeURIComponent(smokePlan.operationId)}/cleanup`,{method:'POST'});setSmokePlan({...smokePlan,...value});}catch(e){onError(e instanceof Error?e.message:'Manifest cleanup could not be retried.');}finally{setSmokeBusy(false);}};
 const canRequest=Boolean(orgId&&txn?.valid&&settle?.valid);
 return <><PageHeading eyebrow="FILE INTAKE" title="Prepare a reconciliation" description="Upload the two source files. The console checks record structure; reconciliation stays on z/OS." action={<span className={`state-pill ${readiness?.liveExecutionEnabled?'online':'offline'}`}><i/>{readiness?.liveExecutionEnabled?'MAINFRAME READY':'EXECUTION DISABLED'}</span>}/>
  {!orgs.length?<section className="panel org-empty"><div className="empty-symbol"><Landmark/></div><h3>Start with organization metadata</h3><p>Reports belong to an organization. Add one in Settings before staging files.</p><a onClick={()=>window.dispatchEvent(new CustomEvent('open-readiness'))}>Open readiness settings <ArrowRight size={14}/></a></section>:<div className="upload-layout"><section className="panel upload-main"><div className="form-row"><label>Organization<select value={orgId} onChange={e=>{onOrg(e.target.value);setTxn(undefined);setSettle(undefined);setPlan(undefined);}}>{orgs.map(o=><option value={o._id} key={o._id}>{o.name} · {o.code}</option>)}</select></label><button className="inline-add" onClick={()=>setNewOrg(v=>!v)}><Plus size={15}/> Add organization</button></div>
   {newOrg&&<form className="new-org-inline" onSubmit={createOrg}><input value={orgName} onChange={e=>setOrgName(e.target.value)} placeholder="Organization name" required maxLength={120}/><input value={orgCode} onChange={e=>setOrgCode(e.target.value)} placeholder="Short code" required maxLength={20}/><button className="button-primary compact">Save</button></form>}
   <div className="upload-cards"><FileDrop label="Transaction file" subtitle="Source transaction records" kind="transaction" info={txn} onFile={f=>void submitFile('transaction',f)}/><FileDrop label="Settlement file" subtitle="Settlement records for matching" kind="settlement" info={settle} onFile={f=>void submitFile('settlement',f)}/></div>
   {notice&&<div className="notice"><Check size={15}/>{notice}<button onClick={()=>setNotice('')}><X size={14}/></button></div>}
   <section className="preview-section"><div className="section-title small-title"><div><h2>Record preview</h2><span>First five records · fixed-width, 38-byte contract</span></div><span className="mini-tag">READ ONLY</span></div><div className="preview-grid"><Preview info={txn} label="TRANSACTION INPUT"/><Preview info={settle} label="SETTLEMENT INPUT"/></div><div className="contract-note"><LockKeyhole size={14}/><span>Contents are staged temporarily. The app does not trim, pad, or rewrite record data.</span></div></section>
   <div className="run-controls"><div><label>Test profile</label><div className="profile-options">{[['SMOKE','Smoke test'],['VOLUME_10K','10K volume'],['NEGATIVE','Negative test']].map(([v,l])=><button key={v} className={profile===v?'selected':''} onClick={()=>{setProfile(v);setPlan(undefined);}}>{profile===v&&<Check size={13}/>} {l}</button>)}</div></div><div className="run-action-group"><button className="button-primary run-button" disabled={!canRequest||planBusy} onClick={()=>void previewPlan()}>{planBusy?'Building plan…':'Preview execution plan'} <ArrowRight size={15}/></button></div></div>
   <section className="panel reconciliation-run-panel" aria-labelledby="reconciliation-run-heading"><div className="panel-head"><div><span className="eyebrow">SEPARATE FROM TRANSFER VERIFICATION</span><h3 id="reconciliation-run-heading">Run reconciliation</h3><p>This workflow must retain its own run datasets, JES evidence, reconciliation outputs and EOD result. The existing transfer test cleans its temporary datasets and is never used for reconciliation.</p></div><Server size={18} className="muted-icon"/></div><div className="reconciliation-run-state"><span className="state-pill offline"><i/>NOT CONFIGURED</span><button className="button-primary" disabled title="Live reconciliation is blocked until the complete run-specific validation and orchestration path is implemented and reviewed.">Run reconciliation</button></div><p className="disabled-note"><TriangleAlert size={16}/><span><b>No reconciliation job will be submitted.</b> The administrator execution gate is independent from file-transfer verification and remains off by default. The run-specific pipeline has offline mock coverage, but generated JCL, JES output parsing and dataset results still require target-system validation.</span></p>{Boolean(readiness?.reconciliationBlockers?.length)&&<ul className="reconciliation-blockers">{readiness?.reconciliationBlockers?.map(item=><li key={item}>{item}</li>)}</ul>}</section>
   <section className="panel transfer-test-panel"><div className="panel-head"><div><span className="eyebrow">SEPARATE CONTROLLED OPERATION</span><h3>Test mainframe file transfer</h3><p>Allocates two temporary PS datasets, transfers these validated uploads, reads them back and cleans only datasets recorded in this operation manifest. It does not submit a job or reconcile records.</p></div><Database size={18} className="muted-icon"/></div><button className="button-secondary" disabled={!canRequest||smokeBusy||smokePlan?.status==='RUNNING'} onClick={()=>void previewSmoke()}>{smokeBusy?'Working…':'Preview transfer test'}</button>{smokePlan&&<div className="transfer-operation"><div className="transfer-summary"><span><small>ORGANIZATION</small><b>{smokePlan.organizationName}</b></span><span><small>OPERATION</small><code>{smokePlan.operationId}</code></span><span><small>STATUS · STAGE</small><b>{statusLabel(smokePlan.status)} · {statusLabel(smokePlan.stage)}</b></span></div><div className="transfer-inputs"><div><b>Transaction</b><span>{smokePlan.inputs.transaction.originalName}</span><small>{fmt(smokePlan.inputs.transaction.size)} bytes · {fmt(smokePlan.inputs.transaction.recordCount)} records</small></div><div><b>Settlement</b><span>{smokePlan.inputs.settlement.originalName}</span><small>{fmt(smokePlan.inputs.settlement.size)} bytes · {fmt(smokePlan.inputs.settlement.recordCount)} records</small></div></div><h4>Exact temporary datasets</h4><div className="transfer-datasets">{smokePlan.datasets.map(ds=><div key={ds.name}><code>{ds.name}</code><span>{ds.kind} · PS / FB / LRECL 38</span><Status status={ds.state}/></div>)}</div>{smokePlan.datasets.some(ds=>!['CLEANED','ALREADY_ABSENT'].includes(ds.state))&&<p className="transfer-gate"><TriangleAlert size={14}/>Remote datasets requiring attention: {smokePlan.datasets.filter(ds=>!['CLEANED','ALREADY_ABSENT'].includes(ds.state)).map(ds=>ds.name).join(', ')}. Unknown creation outcomes require owner review.</p>}<p className="transfer-gate"><LockKeyhole size={14}/>{smokePlan.gateMessage??(smokePlan.canStart?'Execution gates enabled.':'Execution remains disabled by administrator configuration.')}</p>{Object.entries(smokePlan.stageResults).filter(([key])=>key!=='allocationTracks'&&key!=='startedAt').map(([key,value])=><div className="transfer-stage" key={key}><b>{statusLabel(key)}</b><code>{typeof value==='string'?value:JSON.stringify(value)}</code></div>)}{smokePlan.errorMessage&&<div className="alert alert-error" role="alert"><TriangleAlert size={15}/><span>{smokePlan.errorCategory}: {smokePlan.errorMessage}</span></div>}<div className="transfer-actions">{smokePlan.status==='PREPARED'&&<button className="button-primary" disabled={!smokePlan.canStart||smokeBusy} onClick={()=>{setSmokeAcknowledged(false);setSmokeConfirm(true);}}>Confirm planned transfer test</button>}{['CLEANUP_FAILED','VERIFIED_WITH_CLEANUP_WARNING'].includes(smokePlan.status)&&smokePlan.datasets.some(ds=>['CREATED','CLEANING','CLEANUP_FAILED'].includes(ds.state))&&<button className="button-secondary" disabled={smokeBusy} onClick={()=>void retrySmokeCleanup()}>{smokeBusy?'Checking…':'Retry tracked cleanup'}</button>}</div></div>}</section>
   {plan&&<ExecutionPlanView plan={plan} expanded={expandedJcl} onExpand={setExpandedJcl}/>}
  </section><aside className="upload-side"><section className="panel contract-panel"><div className="panel-head"><div><h3>File contract</h3><p>Validated in the backend</p></div><FileCheck2 size={17} className="muted-icon"/></div><div className="contract-list"><ContractItem index="01" title="Transaction ID" bytes="1–10 · 10 characters"/><ContractItem index="02" title="Account ID" bytes="11–20 · 10 characters"/><ContractItem index="03" title="Amount" bytes="21–29 · 9 digits"/><ContractItem index="04" title="Date" bytes="30–37 · YYYYMMDD"/><ContractItem index="05" title="Status" bytes="38 · 1 character"/></div><div className="contract-foot">FB · LRECL=38 · Plain text</div></section><section className="info-callout"><ShieldCheck size={18}/><div><b>Mainframe remains the source of truth</b><p>Matching, amount validation, exception generation and EOD publication run on z/OS only.</p></div></section><div className="retention-note"><Database size={15}/><span>Upload staging is temporary and expires automatically after 24 hours.</span></div></aside></div>}
  {smokeConfirm&&smokePlan&&<div className="modal-backdrop"><div className="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="smoke-confirm-title"><button className="modal-close" onClick={()=>setSmokeConfirm(false)} aria-label="Close confirmation"><X size={18}/></button><div className="modal-icon"><ShieldCheck/></div><div className="eyebrow">FILE TRANSFER ONLY · NO JES JOB</div><h2 id="smoke-confirm-title">Confirm mainframe file-transfer test</h2><p>This operation creates, uploads, reads back and deletes only the two listed datasets. It does not run sorting, VSAM, COBOL, EOD or reconciliation.</p><div className="confirm-summary"><span>{smokePlan.organizationName}</span>{smokePlan.datasets.map(ds=><code key={ds.name}>{ds.name}</code>)}</div><label className="smoke-acknowledge"><input type="checkbox" checked={smokeAcknowledged} onChange={e=>setSmokeAcknowledged(e.target.checked)}/> I explicitly authorize this one-time file-transfer verification and confirm these exact dataset names.</label><div className="modal-actions"><button className="button-quiet" onClick={()=>setSmokeConfirm(false)}>Cancel</button><button className="button-primary" onClick={()=>void startSmoke()} disabled={!smokeAcknowledged||!smokePlan.canStart||smokeBusy}>{smokeBusy?'Starting…':'Start transfer verification'}</button></div></div></div>}
 </>;
}
function ExecutionPlanView({plan,expanded,onExpand}:{plan:PlanPreview;expanded?:number;onExpand:(n:number|undefined)=>void}){
 return <section className="panel execution-plan" aria-labelledby="execution-plan-heading"><div className="plan-header"><div><span className="eyebrow">NON-MUTATING · NOT SUBMITTED</span><h2 id="execution-plan-heading">Execution plan preview</h2><p><code>{plan.runId}</code> · {plan.organization.name} · {statusLabel(plan.profile)}</p></div><span className="state-pill offline">PLAN ONLY</span></div>
  <div className="plan-inputs"><div><b>Transaction input</b><span>{plan.inputs.transaction.originalName}</span><small>{fmt(plan.inputs.transaction.size)} bytes · {fmt(plan.inputs.transaction.recordCount)} validated records</small></div><div><b>Settlement input</b><span>{plan.inputs.settlement.originalName}</span><small>{fmt(plan.inputs.settlement.size)} bytes · {fmt(plan.inputs.settlement.recordCount)} validated records</small></div></div>
  <div className="plan-block"><h3>Planned datasets</h3><p>Names below are reserved in this proposal only. None have been created.</p><div className="table-wrap"><table><thead><tr><th>Dataset</th><th>Purpose</th><th>Format</th><th>Planned space</th><th>State</th></tr></thead><tbody>{plan.datasets.map(ds=><tr key={ds.name}><td><code>{ds.name}</code></td><td>{ds.purpose}</td><td>{ds.format}</td><td><code>{ds.space}</code></td><td><span className="state-pill offline">PLANNED</span></td></tr>)}</tbody></table></div></div>
  <div className="plan-block"><h3>Ordered processing steps</h3><div className="plan-steps">{plan.steps.map(step=><article className="plan-step" key={step.order}><div className="plan-step-head"><span className="step-number">{String(step.order).padStart(2,'0')}</span><div><h4>{step.name}</h4><p>{step.purpose}</p></div><span className={`state-pill ${step.state==='BLOCKED'?'offline':'planned'}`}>{step.state==='BLOCKED'?'BLOCKED':'PLAN ONLY'}</span></div>{step.dependencies.length>0&&<p className="plan-dependencies"><b>Depends on:</b> {step.dependencies.join(' → ')}</p>}<div className="plan-columns"><div><b>Expected DDs / record formats</b>{step.expectedDd.map(dd=><code key={dd}>{dd}</code>)}</div><div><b>Required gates</b><ul>{step.checks.map(check=><li key={check}>{check}</li>)}</ul></div></div>{step.jcl?<div className="jcl-preview"><button type="button" className="text-btn" aria-expanded={expanded===step.order} onClick={()=>onExpand(expanded===step.order?undefined:step.order)}>{expanded===step.order?'Hide':'View'} generated JCL <ChevronDown size={14}/></button>{expanded===step.order&&<pre aria-label={`${step.name} generated JCL`}><code>{step.jcl}</code></pre>}</div>:<p className="jcl-unavailable">JCL not generated: {step.jclUnavailableReason}</p>}</article>)}</div></div>
  <div className="plan-block cleanup-block"><h3>Run-scoped cleanup manifest</h3><p>{plan.cleanupManifest.policy}</p><b>Temporary candidates — no deletion authorized</b><div className="dataset-chip-list">{plan.cleanupManifest.temporaryDatasetCandidates.map(n=><code key={n}>{n}</code>)}</div><b>Retained output / diagnostic candidates</b><div className="dataset-chip-list">{plan.cleanupManifest.retainedDatasetCandidates.map(n=><code key={n}>{n}</code>)}</div></div>
  <div className="plan-limitations"><h3><TriangleAlert size={16}/> Execution blockers and review items</h3><ul>{plan.limitations.map(item=><li key={item}>{item}</li>)}</ul><p>Live execution remains disabled. This preview is not an approval to run these jobs.</p></div>
 </section>;
}
function FileDrop({label,subtitle,kind,info,onFile}:{label:string;subtitle:string;kind:string;info?:UploadInfo;onFile:(f?:File)=>void}){const [drag,setDrag]=useState(false);return <label className={`file-drop ${drag?'drag-over':''} ${info?.valid?'file-valid':''}`} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);onFile(e.dataTransfer.files[0]);}}><input type="file" accept=".txt,text/plain" onChange={e=>onFile(e.target.files?.[0])}/><div className="drop-head"><div className="drop-icon"><UploadCloud size={19}/></div><div><b>{label}</b><small>{subtitle}</small></div>{info&&<span className={`check-badge ${info.valid?'passed':'failed'}`}>{info.valid?<Check size={13}/>:<TriangleAlert size={13}/>}</span>}</div>{info?<div className="file-info"><div className="file-detail"><FileText size={15}/><span><b>{info.originalName}</b><small>{(info.size/1024).toFixed(1)} KB · {info.recordCount.toLocaleString()} records</small></span><span className={`validation-text ${info.valid?'good':'bad'}`}>{info.valid?'Contract passed':'Review errors'}</span></div>{info.errors.length>0&&<ul className="file-errors">{info.errors.slice(0,4).map((err,i)=><li key={i}>{err}</li>)}</ul>}<span className="replace-hint">Click or drop to replace</span></div>:<div className="drop-prompt"><b>Drop your .txt file here</b><span>or <u>browse files</u> · max 10 MB</span></div>}<div className="drop-kind">{kind.toUpperCase()} · .TXT</div></label>}
