function SettingsPage({readiness,orgs,onOrgs,onOrg,onError}:{readiness?:Readiness;orgs:Org[];onOrgs:(o:Org[])=>void;onOrg:(id:string)=>void;onError:(s:string)=>void}){
 const [name,setName]=useState('');const [code,setCode]=useState('');const [busy,setBusy]=useState(false);const [testBusy,setTestBusy]=useState(false);const testInFlight=useRef(false);const [connection,setConnection]=useState<ConnectionResult>();
 useEffect(()=>{const fn=()=>document.getElementById('settings-title')?.scrollIntoView({behavior:'smooth'});window.addEventListener('open-readiness',fn);return()=>window.removeEventListener('open-readiness',fn);},[]);
 const add=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{const org=await api<Org>('/api/organizations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,code})});onOrgs([...orgs,org]);onOrg(org._id);setName('');setCode('');}catch(e){onError(e instanceof Error?e.message:'Could not add organization.');}finally{setBusy(false);}};
 const testConnection=async(e:React.FormEvent)=>{e.preventDefault();if(testInFlight.current)return;testInFlight.current=true;setTestBusy(true);setConnection(undefined);try{const response=await fetch('/api/mainframe/connection-test',{method:'POST',credentials:'include'});const result=await response.json().catch(()=>null) as (ConnectionResult&{message?:string})|null;if(!result||typeof result.message!=='string')throw new Error('The API returned an unreadable connection-test response.');setConnection(result);}catch(e){setConnection({profile:'zosmf',state:'CONNECTION_FAILED',connectionStatus:'FAILED',datasetAccessStatus:'NOT_TESTED',message:e instanceof Error?e.message:'The API did not return a connection-test result.',executionEnabled:false});}finally{testInFlight.current=false;setTestBusy(false);}};
 const statusTitle=connection?.state==='DATASET_ACCESS_VERIFIED'?'Dataset access verified':connection?.state==='DATASET_ACCESS_FAILED'?'Dataset access failed':connection?.state==='CLI_UNAVAILABLE'?'Zowe CLI unavailable':connection?.state==='CONNECTION_VERIFIED'?'Connection verified':connection?.state==='CONNECTION_FAILED'?'Connection failed':'Not tested';
 return <><PageHeading eyebrow="CONFIGURATION" title="Mainframe readiness" description="Check the local Zowe CLI profile and read-only test dataset. A successful check does not enable job execution."/><div id="settings-title" className="readiness-banner"><div className="readiness-banner-icon"><Server/></div><div><span className="eyebrow">EXECUTION GATE</span><h2>{connection?.state==='DATASET_ACCESS_VERIFIED'?'Connection verified; dataset access verified':connection?.state==='DATASET_ACCESS_FAILED'?'Connection verified; dataset access failed':connection?.state==='CONNECTION_FAILED'?'Connection not established':connection?.state==='CLI_UNAVAILABLE'?'Zowe CLI unavailable':readiness?.liveExecutionEnabled?'Execution gate requires administrator review':'Live execution not configured'}</h2><p>{connection?.message??readiness?.message??'Readiness status is unavailable.'}</p></div><span className="state-pill offline"><i/>EXECUTION DISABLED</span></div>
 <div className="settings-grid"><section className="panel"><div className="panel-head"><div><h3>Read-only connection test</h3><p>The API uses the Zowe CLI profile available to the local Windows account running the backend.</p></div><LockKeyhole size={17} className="muted-icon"/></div><ReadinessRows readiness={readiness} connectionOverride={connection?.state}/><div className="readiness-rows"><ReadinessRow label="Dataset access" value={connection?.datasetAccessStatus??'NOT TESTED'} ok={connection?.datasetAccessStatus==='VERIFIED'}/></div><div className="connection-profile"><span>Configured profile</span><code>zosmf</code><small>Profile name presence does not prove that the profile is authenticated.</small></div><form className="connection-form" onSubmit={testConnection}><button className="button-primary" disabled={testBusy}><Activity size={15}/>{testBusy?'Testing connection…':'Test connection'}</button></form>{connection&&<div className={`connection-result ${connection.state==='CONNECTION_FAILED'||connection.state==='DATASET_ACCESS_FAILED'||connection.state==='CLI_UNAVAILABLE'?'connection-failed':'connection-success'}`} role="status" aria-live="polite"><b>{statusTitle}</b><p>{connection.message}</p><small>Connection: {connection.connectionStatus}</small><small>Dataset access: {connection.datasetAccessStatus}</small>{connection.datasetAttributes&&<small>Dataset: <code>{connection.dataset}</code>{connection.datasetAttributes.dsorg?` · ${connection.datasetAttributes.dsorg}`:''}{connection.datasetAttributes.recfm?` · ${connection.datasetAttributes.recfm}`:''}{connection.datasetAttributes.lrecl?` · LRECL ${connection.datasetAttributes.lrecl}`:''}</small>}</div>}<div className="settings-notice"><TriangleAlert size={16}/><p>Only read-only CLI checks are made. This does not upload files, allocate datasets, submit jobs, or enable mainframe execution.</p></div></section><section className="panel org-panel"><div className="panel-head"><div><h3>Organizations</h3><p>Metadata used to label each run and report</p></div><Landmark size={17} className="muted-icon"/></div>{orgs.length?<div className="org-list">{orgs.map(o=><div key={o._id}><span className="org-avatar">{o.code.slice(0,2)}</span><b>{o.name}<small>{o.code}</small></b><Check size={15}/></div>)}</div>:<div className="org-none">No organizations added yet.</div>}<form className="org-form" onSubmit={add}><label>Organization name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2} maxLength={120} placeholder="e.g. Example Bank"/></label><label>Short code<input value={code} onChange={e=>setCode(e.target.value)} required maxLength={20} pattern="[A-Za-z0-9_-]+" placeholder="e.g. EXB"/></label><button className="button-primary" disabled={busy}><Plus size={15}/>{busy?'Adding…':'Add organization'}</button></form></section></div><section className="panel next-steps"><div className="panel-head"><div><h3>Integration path</h3><p>Job execution remains disabled until the later integration phases are verified</p></div></div><div className="steps-grid"><Step number="01" title="Administrator configuration" text="Set server-only endpoint, approved HLQ, job class and libraries."/><Step number="02" title="Implement the adapter" text="Transfer run-scoped input datasets and submit the approved JCL through z/OSMF/JES."/><Step number="03" title="Verify job output" text="Retrieve JES evidence, parse real counts, exceptions and EOD publication status."/><Step number="04" title="Enable after verification" text="Test authorization, permissions and connection before enabling live execution."/></div></section></>;
}
