 const loadScopes=useCallback(async()=>{try{const result=await api<{scopes:string[];unavailableReason:string;mutationBlockers:string[];recoveryEnabled:boolean}>('/api/mainframe/datasets/scopes');setScopes(result.scopes);setMutationBlockers(result.mutationBlockers);setRecoveryEnabled(result.recoveryEnabled);setScope(current=>current||result.scopes[0]||'');if(!result.scopes.length)setError(result.unavailableReason);}catch(e){setError(e instanceof Error?e.message:'Dataset scopes unavailable.');}},[]);
 const loadOwned=useCallback(async()=>{try{const result=await api<{items:typeof owned;mutationBlockers:string[]}>('/api/mainframe/owned-datasets');setOwned(result.items);setMutationBlockers(result.mutationBlockers);}catch(e){setError(e instanceof Error?e.message:'Owned dataset manifest unavailable.');}},[]);
