 const loadList=useCallback(async()=>{if(!scope)return;setBusy(true);setError('');try{const result=await api<{datasets:DatasetRow[]}>(`/api/mainframe/datasets?scope=${encodeURIComponent(scope)}`);setRows(result.datasets);}catch(e){setRows([]);setError(e instanceof Error?e.message:'Dataset listing failed.');}finally{setBusy(false);}},[scope]);
 useEffect(()=>{void loadScopes();void loadOwned();void loadOperations();},[loadScopes,loadOwned,loadOperations]);useEffect(()=>{if(scope)void loadList();},[scope,loadList]);
 const inspect=async(name:string)=>{setSelected(name);setAttrs(undefined);setRecords(undefined);setRecordSummary('');setError('');try{const data=await api<{attributes:Record<string,unknown>}>(`/api/mainframe/datasets/${encodeURIComponent(name)}/attributes?scope=${encodeURIComponent(scope)}`);setAttrs(data.attributes);}catch(e){setError(e instanceof Error?e.message:'Dataset attributes unavailable.');}};
