 const download=async()=>{if(!selected)return;try{const response=await fetch(`/api/mainframe/datasets/${encodeURIComponent(selected)}/content?scope=${encodeURIComponent(scope)}&download=true`,{credentials:'include'});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message??`Dataset download failed (${response.status}).`);}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${selected.replaceAll('.','_')}.txt`;link.click();URL.revokeObjectURL(url);setNotice(`Downloaded verified contents from ${selected}.`);}catch(e){setError(e instanceof Error?e.message:'Dataset download failed.');}};
 const create=async()=>{setBusy(true);setError('');setNotice('');try{const result=await api<{operationId:string;dataset:string;state:string;attributes:Record<string,unknown>;allocation:Record<string,unknown>}>('/api/mainframe/owned-datasets',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({primaryTracks,secondaryTracks})});setNotice(`Created and verified ${result.dataset} as PS/FB/LRECL=38 (${primaryTracks} primary + ${secondaryTracks} secondary tracks). Operation ${result.operationId}.`);await loadOwned();await loadOperations();if(scope)await loadList();}catch(e){setError(e instanceof Error?e.message:'Dataset creation failed or is unresolved.');await loadOwned();await loadOperations();}finally{setBusy(false);}};
 const transfer=async(item:typeof owned[number],file?:File)=>{if(!file)return;const replacing=item.state==='ACTIVE';if(replacing&&!window.confirm(`Replace all records in ${item.dataset}? Zowe uploads by PUT and replaces the complete data set contents. The operation reports success only after remote read-back matches the file.`))return;setBusy(true);setError('');setNotice('');try{const form=new FormData();form.set('file',file);if(replacing)form.set('confirmDataset',item.dataset);const result=await api<{operationId:string;dataset:string;state:string;recordCount:number;contentMatch:boolean}>(`/api/mainframe/owned-datasets/${encodeURIComponent(item._id)}/content`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:form});setNotice(`${replacing?'Replaced':'Uploaded'} ${result.recordCount} records to ${result.dataset}; remote read-back ${result.contentMatch?'matched':'did not match'}. Operation ${result.operationId}.`);await loadOwned();await loadOperations();if(scope)await loadList();}catch(e){setError(e instanceof Error?e.message:'Dataset upload failed or is unresolved.');await loadOwned();await loadOperations();}finally{setBusy(false);}};
