type JobStatusResult={runId:string;jobId:string;status:string;returnCode:number|null;conditionCode?:string;steps:Array<{stage?:string;stepName?:string;status:string;returnCode?:number;conditionCode?:string}>;businessSummary:Record<string,number>;eodDecision:string};
function JobsSpoolPage({onOpenRun}:{onOpenRun:(id:string)=>void}){
 const [runs,setRuns]=useState<Run[]>([]),[smokeJobs,setSmokeJobs]=useState<SmokeJob[]>([]),[selectedRun,setSelectedRun]=useState(''),[status,setStatus]=useState<JobStatusResult>(),[selectedSmoke,setSelectedSmoke]=useState<SmokeJob>(),[runSpool,setRunSpool]=useState(''),[submission,setSubmission]=useState<{enabled:boolean;approvedTemplates:string[];blockers:string[];message:string}>(),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const pollCount=useRef({operationId:'',count:0});
 const refresh=useCallback(async()=>{setBusy(true);setError('');try{const [h,j]=await Promise.all([api<History>('/api/runs?page=1&pageSize=50&sort=createdAt&order=desc'),api<{items:SmokeJob[]}>('/api/mainframe/jobs/operations')]);setRuns(h.items.filter(run=>Boolean(run.jobId)));setSmokeJobs(j.items);}catch(e){setError(e instanceof Error?e.message:'Saved job history unavailable.');}finally{setBusy(false);}},[]);
 const checkSmoke=useCallback(async(operationId:string)=>{try{const detail=await api<SmokeJob>(`/api/mainframe/jobs/operations/${encodeURIComponent(operationId)}`);setSelectedSmoke(detail);setSmokeJobs(current=>[detail,...current.filter(item=>item.operationId!==detail.operationId)]);}catch(e){setError(e instanceof Error?e.message:'Saved JES operation could not be refreshed.');}},[]);
 useEffect(()=>{void refresh();void api<{enabled:boolean;approvedTemplates:string[];blockers:string[];message:string}>('/api/mainframe/jobs/submission-readiness').then(setSubmission).catch(e=>setSubmission({enabled:false,approvedTemplates:[],blockers:[],message:e instanceof Error?e.message:'Submission readiness unavailable.'}));},[refresh]);
 useEffect(()=>{if(!selectedSmoke?.operationId||!['SUBMITTED','RUNNING'].includes(selectedSmoke.state))return;if(pollCount.current.operationId!==selectedSmoke.operationId)pollCount.current={operationId:selectedSmoke.operationId,count:0};if(pollCount.current.count>=4)return;const timer=window.setTimeout(()=>{pollCount.current.count+=1;void checkSmoke(selectedSmoke.operationId);},2500);return()=>window.clearTimeout(timer);},[selectedSmoke?.operationId,selectedSmoke?.state,checkSmoke]);
 const checkRun=async(runId:string)=>{setSelectedRun(runId);setBusy(true);setError('');try{setStatus(await api<JobStatusResult>(`/api/runs/${encodeURIComponent(runId)}/job-status`));}catch(e){setStatus(undefined);setError(e instanceof Error?e.message:'JES status unavailable.');}finally{setBusy(false);}};
 const submitSmoke=async()=>{setBusy(true);setError('');try{const result=await api<SmokeJob>('/api/mainframe/jobs/noop-smoke',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:'{}'});setSelectedSmoke(result);setSmokeJobs(current=>[result,...current.filter(item=>item.operationId!==result.operationId)]);await refresh();}catch(e){setError(e instanceof Error?e.message:'The smoke-job outcome is unavailable; inspect saved operations before taking action.');await refresh();}finally{setBusy(false);}};
 const downloadSmokeSpool=()=>{if(!selectedSmoke?.spoolText)return;const url=URL.createObjectURL(new Blob([selectedSmoke.spoolText],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${selectedSmoke.jobId??selectedSmoke.operationId}-spool.txt`;link.click();URL.revokeObjectURL(url);};
 const getRunSpool=async()=>{if(!selectedRun)return;setBusy(true);setError('');try{const result=await api<{spoolText:string;spoolTruncated:boolean}>(`/api/runs/${encodeURIComponent(selectedRun)}/spool`);setRunSpool(result.spoolText);if(result.spoolTruncated)setError('Retrieved run spool is truncated at the server evidence limit.');}catch(e){setError(e instanceof Error?e.message:'JES spool unavailable.');}finally{setBusy(false);}};
 const downloadRunSpool=()=>{if(!runSpool)return;const url=URL.createObjectURL(new Blob([runSpool],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${selectedRun}-spool.txt`;link.click();URL.revokeObjectURL(url);};
 return <><PageHeading eyebrow="JES OPERATIONS" title="Jobs & spool" description="Inspect persisted job operations and actual JES evidence. The only enabled submission template is a harmless IEFBR14 smoke job." action={<button className="button-quiet" disabled={busy} onClick={()=>void refresh()}><RefreshCw size={15}/>Refresh jobs</button>}/><div className="workbench-notice"><LockKeyhole size={16}/><span>Job submission requires an authenticated application session and the server-side <code>MAINFRAME_JOB_SUBMISSION_ENABLED</code> gate. No browser-supplied JCL is accepted.</span></div>{error&&<div className="alert alert-error" role="alert"><TriangleAlert size={16}/><span>{error}</span></div>}
 <section className="panel unsupported-panel"><div><h3>Approved job template · NOOP_SMOKE</h3><p>{submission?.message??'Checking server configuration…'} It runs <code>IEFBR14</code> without DD statements or dataset operations. This is not a reconciliation job.</p>{submission?.blockers.map(item=><small className="blocker-line" key={item}>{item}</small>)}</div><button className="button-primary" disabled={busy||!submission?.enabled||!submission.approvedTemplates.includes('NOOP_SMOKE')} title={submission?.blockers.join(' ')||'Only the fixed NOOP_SMOKE template is permitted.'} onClick={()=>void submitSmoke()}><Activity size={15}/>{busy?'Working…':'Submit NOOP_SMOKE'}</button></section>
 <section className="panel jobs-panel"><div className="panel-head"><div><h3>Smoke-job operations</h3><p>Independent persisted job records; uncertain submission outcomes cannot be resubmitted.</p></div></div>{smokeJobs.length?<div className="table-wrap"><table><thead><tr><th>OPERATION</th><th>TEMPLATE / NAME</th><th>SUBMITTED</th><th>JES JOB</th><th>STATUS</th><th>RC</th><th/></tr></thead><tbody>{smokeJobs.map(item=><tr key={item.operationId}><td><code>{item.operationId}</code></td><td>{item.template} · <code>{item.jobName}</code></td><td>{dateTime(item.submittedAt??item.createdAt)}</td><td><code>{item.jobId??'Not confirmed'}</code></td><td><Status status={item.state}/></td><td>{item.returnCode??'—'}</td><td><button className="button-secondary" disabled={busy} onClick={()=>void checkSmoke(item.operationId)}>Refresh evidence</button></td></tr>)}</tbody></table></div>:<div className="table-empty"><BriefcaseBusiness size={20}/><b>{busy?'Loading saved jobs…':'No smoke-job operations recorded'}</b><span>{submission?.enabled?'Submit the approved NOOP_SMOKE template to create a separate job record.':'The submit action remains unavailable until its server-side configuration is valid.'}</span></div>}</section>
 {selectedSmoke&&<section className="panel job-evidence"><div className="panel-head"><div><h3>Smoke-job evidence · <code>{selectedSmoke.jobId??selectedSmoke.operationId}</code></h3><p>{selectedSmoke.template} · generated name <code>{selectedSmoke.jobName}</code> · operation {selectedSmoke.operationId}</p></div><div className="export-actions"><button className="button-secondary" disabled={busy||!selectedSmoke.jobId||['COMPLETED','FAILED'].includes(selectedSmoke.state)} onClick={()=>void checkSmoke(selectedSmoke.operationId)}><RefreshCw size={15}/>Refresh JES</button><button className="button-quiet" disabled={!selectedSmoke.spoolText} onClick={downloadSmokeSpool}><Download size={15}/>Download spool</button></div></div><div className="job-evidence-grid"><div><small>OPERATION STATE</small><b>{selectedSmoke.state}</b></div><div><small>JES STATUS</small><b>{selectedSmoke.jobStatus??'Not confirmed'}</b></div><div><small>RETURN CODE</small><code>{selectedSmoke.returnCode??'Not returned'}</code></div><div><small>CONDITION</small><code>{selectedSmoke.conditionCode??'Not returned'}</code></div></div><DetailLine label="Submitted" value={dateTime(selectedSmoke.submittedAt)}/><DetailLine label="Last checked" value={dateTime(selectedSmoke.lastCheckedAt)}/><DetailLine label="Spool retrieved" value={dateTime(selectedSmoke.spoolRetrievedAt)}/>{selectedSmoke.errorCategory&&<p className="auth-form-error" role="status">{selectedSmoke.errorCategory}: {selectedSmoke.errorMessage??'The operation requires review.'}</p>}{selectedSmoke.state==='SUBMISSION_UNCERTAIN'&&<p className="muted-copy">The submission response was inconclusive. No automatic resubmission is available; verify this operation with JES before taking further action.</p>}{selectedSmoke.spoolText?<><pre className="spool-view">{selectedSmoke.spoolText}</pre>{selectedSmoke.spoolTruncated&&<small className="muted-copy">Stored spool was truncated at the server evidence limit.</small>}</>:<p className="muted-copy">No spool evidence has been retrieved yet. A terminal JES OUTPUT result and return code are required before the operation is marked complete.</p>}</section>}
 <section className="panel jobs-panel"><div className="panel-head"><div><h3>Jobs associated with reconciliation runs</h3><p>Reconciliation remains NOT_CONFIGURED / HTTP 503.</p></div></div>{runs.length?<div className="table-wrap"><table><thead><tr><th>RUN ID</th><th>JES JOB</th><th>SUBMITTED</th><th>STORED STATUS</th><th/></tr></thead><tbody>{runs.map(run=><tr key={run.runId}><td><button className="text-btn" onClick={()=>onOpenRun(run.runId)}>{run.runId}</button></td><td><code>{run.jobId}</code></td><td>{dateTime(run.createdAt)}</td><td><Status status={run.jobStatus??run.status}/></td><td><button className="button-secondary" disabled={busy} onClick={()=>void checkRun(run.runId)}>Refresh JES</button></td></tr>)}</tbody></table></div>:<div className="table-empty"><BriefcaseBusiness size={20}/><b>No reconciliation jobs</b><span>No banking reconciliation jobs are submitted from this page.</span></div>}</section>{status&&<section className="panel job-evidence"><div className="panel-head"><div><h3>Reconciliation JES evidence · <code>{status.jobId}</code></h3><p>Run {status.runId}</p></div><div className="export-actions"><button className="button-secondary" disabled={busy} onClick={()=>void getRunSpool()}><FileText size={15}/>Retrieve spool</button><button className="button-quiet" disabled={!runSpool} onClick={downloadRunSpool}><Download size={15}/>Download spool</button></div></div><div className="job-evidence-grid"><div><small>STATUS</small><b>{status.status}</b></div><div><small>RETURN CODE</small><code>{status.returnCode??'Not returned'}</code></div><div><small>CONDITION</small><code>{status.conditionCode??'Not returned'}</code></div><div><small>EOD DECISION</small><b>Not available</b></div></div>{status.steps.length?<div className="table-wrap"><table><thead><tr><th>STEP</th><th>STATUS</th><th>RC</th><th>CONDITION</th></tr></thead><tbody>{status.steps.map((step,index)=><tr key={index}><td>{step.stepName??step.stage??`Step ${index+1}`}</td><td>{step.status}</td><td>{step.returnCode??'—'}</td><td>{step.conditionCode??'—'}</td></tr>)}</tbody></table></div>:<p className="muted-copy">No validated step-level result is stored for this run.</p>}</section>}{runSpool&&<section className="panel job-evidence"><h3>Retrieved reconciliation spool</h3><pre className="spool-view">{runSpool}</pre></section>}</>;
}function Step({number,title,text}:{number:string;title:string;text:string}){return <div><span>{number}</span><b>{title}</b><p>{text}</p></div>}
